def gen(rng):
    def build(n, q, step=10, start=None, doubling=False):
        if start is None:
            start = rng.randint(-10**9, -10**9 + 40)
        if doubling:
            arr = [start + (2**i if i < 28 else 2**27 + i) for i in range(n)]
        else:
            arr = []
            v = start
            for i in range(n):
                arr.append(v)
                v += rng.randint(1, step)
        lo, hi = max(-10**9, arr[0] - 5), min(10**9, arr[-1] + 5)
        qs = []
        for _ in range(q):
            t = rng.random()
            if t < 0.5:
                qs.append(rng.choice(arr))
            elif t < 0.7:
                qs.append(max(-10**9, min(10**9, rng.choice(arr) + rng.choice([-1, 1]))))
            else:
                qs.append(rng.randint(lo, hi))
        return f'{n}\n' + ' '.join(map(str, arr)) + f'\n{q}\n' + '\n'.join(map(str, qs))
    tests = [build(1, 4, 3), build(2, 5, 3), build(3, 6, 5)]
    for _ in range(12):
        tests.append(build(rng.randint(1, 15), rng.randint(1, 10), rng.choice([1, 3, 50])))
    tests.append(build(20, 15, doubling=True, start=-10**9 + 5))
    tests.append(build(100000, 50000, 19999, start=-10**9))
    tests.append(build(100000, 50000, 5))
    tests.append(build(65536, 50000, 100))
    tests.append(build(1, 50000, 1))
    return tests
